 void OpenKeyDraft(){CancelKeyCapture();keyDraft=KeyConfigService.Ensure().Copy();draftCharacter=player.InputCharacter?.characterId;pendingOperation=null;focusKeyBattle=true;if(keyDialog!=null)SetKeyModal(false);if(keyStatus!=null)keyStatus.text=KeyConfigService.Status+" / 保存するまでゲームは変わりません";RefreshInputOptions();FlushKeyInput();}
 void SetKeyTab(bool character){CancelKeyCapture();characterMode=character;focusKeyBattle=true;pendingOperation=null;RefreshInputOptions();EventSystem.current?.SetSelectedGameObject((character?characterTab:basicTab).gameObject);}
 static string OpName(string name){switch(name){case "LP":return "弱P";case "MP":return "中P";case "HP":return "強P";case "LK":return "弱K";case "MK":return "中K";case "HK":return "強K";default:return name;}}
 string RowName(string id){if(id.StartsWith("battle.")&&Enum.TryParse(id.Substring(7),out BattleAttackSlot slot)){var c=player.InputCharacter;var op=c==null?null:Array.Find(c.attackSlots,x=>keyDraft.Slot(c,x)==(int)slot);return slot+(op==null?"":"〔"+OpName(op.displayName)+"〕");}return id.Substring(id.IndexOf('.')+1);}
 public static string BindingText(string value){if(string.IsNullOrEmpty(value))return "—";string path=KeyConfigProfile.PathPart(value);string text=path.Substring(path.IndexOf("/",StringComparison.Ordinal)+1);switch(text){case "buttonWest":text="□";break;case "buttonNorth":text="△";break;case "buttonEast":text="○";break;case "buttonSouth":text="×";break;case "leftShoulder":text="L1";break;case "rightShoulder":text="R1";break;case "leftTrigger":text="L2";break;case "rightTrigger":text="R2";break;case "leftStickPress":text="L3";break;case "rightStickPress":text="R3";break;case "start":text="Options";break;default:if(path.StartsWith("<Keyboard>"))text=text.ToUpperInvariant();break;}int m=KeyConfigProfile.Modifier(value);return (m==0?"":"T"+m+"+")+text;}
 public void StartKeyCapture(string id){if(keyDraft==null)return;CancelKeyCapture();captureId=id;keyCapture=new KeyBindingCapture(keyDraft,keyDraft.Row(id).context=="Trigger");keyStatus.text=RowName(id)+": ボタンを離してから入力。Escも登録可能です";FlushKeyInput();}
 public void DiscardKeyDraftOnClose(){if(OptionInputSettingsVisible&&inputOptions!=null)OpenKeyDraft();}
 public void CancelKeyCapture(){bool active=keyCapture!=null;keyCapture?.Dispose();keyCapture=null;if(active)FlushKeyInput();}
 public bool ProposeKeyBinding(string id,bool pad,string value){bool ok=keyDraft.TryBinding(id,pad,value,false,out var conflict,out var error);if(ok){keyStatus.text="draftを変更しました（未保存）";RefreshInputOptions();return true;}if(conflict!=null&&error==null){pendingId=id;pendingPad=pad;pendingValue=value;pendingOperation=null;ShowKeySwap(RowName(conflict)+" と入れ替えますか？");}else keyStatus.text=error;return false;}
 public void CancelKeySwap(){pendingOperation=null;SetKeyModal(false);FlushKeyInput();RefreshInputOptions();RestoreKeyFocus();}
 void SetKeyModal(bool visible){keyDialog.SetActive(visible);var group=keyContent.GetComponent<CanvasGroup>();if(group==null)group=keyContent.AddComponent<CanvasGroup>();group.interactable=!visible;group.blocksRaycasts=!visible;foreach(string name in new[]{"SaveKeys","CancelKeys","DefaultKeys","BackKeys"})inputOptions.transform.Find(name).GetComponent<Button>().interactable=!visible;}
 void ShowKeySwap(string text){keyReturnFocus=EventSystem.current?.currentSelectedGameObject;SetKeyModal(true);keyDialog.transform.SetAsLastSibling();keyDialog.transform.Find("Message").GetComponent<Text>().text=text;EventSystem.current?.SetSelectedGameObject(keyDialog.transform.Find("No").gameObject);FlushKeyInput();}
 public void ConfirmKeySwap(){if(pendingOperation!=null){keyDraft.SwapOperation(player.InputCharacter,pendingOperation,pendingSlot);keyStatus.text="キャラ配置draftを入れ替えました";}else keyStatus.text=keyDraft.TryBinding(pendingId,pendingPad,pendingValue,true,out _,out var error)?"binding draftを交換しました":error;pendingOperation=null;SetKeyModal(false);FlushKeyInput();RefreshInputOptions();RestoreKeyFocus();}
 void RestoreKeyFocus(){if(keyReturnFocus!=null&&keyReturnFocus.activeInHierarchy)EventSystem.current?.SetSelectedGameObject(keyReturnFocus);else EventSystem.current?.SetSelectedGameObject((characterMode?characterTab:basicTab).gameObject);}
 int pendingSlot;
 void SelectKeyOperation(int index){var c=player.InputCharacter;if(c==null||index>=c.attackSlots.Length)return;pendingOperation=KeyConfigProfile.OpId(c.attackSlots[index]);keyStatus.text=OpName(c.attackSlots[index].displayName)+": 移動先slotを選択してください";RefreshInputOptions();}
 void ChooseKeySlot(BattleAttackSlot slot){if(pendingOperation==null)return;pendingSlot=(int)slot;var c=player.InputCharacter;var other=Array.Find(c.attackSlots,x=>keyDraft.Slot(c,x)==pendingSlot);ShowKeySwap((other==null?"このslot":OpName(other.displayName))+" と配置を入れ替えますか？");}
 public bool SaveKeyConfigDraft(out string error){if(!KeyConfigService.Save(keyDraft,out error))return false;ReloadUserInput();return true;}
 public void ReloadUserInput(){player.GetComponent<TrainingControls>()?.ReloadBindings();player.opponent.GetComponent<TrainingSecondPlayerControls>()?.ReloadBindings();menuInput?.Dispose();menuInput=new TrainingMenuInput();FlushKeyInput();}
 void SaveKeyDraft(){CancelKeyCapture();keyStatus.text=SaveKeyConfigDraft(out var error)?"保存して反映しました":error;}
 void FlushKeyInput(){menuInput?.Clear();keyUiBlockFrame=Time.frameCount+2;}
 void UpdateKeyConfig(){if(!OptionVisible||!OptionInputSettingsVisible){CancelKeyCapture();return;}if(draftCharacter!=player.InputCharacter?.characterId){CancelKeyCapture();draftCharacter=player.InputCharacter?.characterId;pendingOperation=null;RefreshInputOptions();}if(keyCapture!=null){keyCapture.Tick();keyStatus.text=keyCapture.Status;if(keyCapture.Complete){string id=captureId,value=keyCapture.Value;bool pad=keyCapture.Pad;CancelKeyCapture();ProposeKeyBinding(id,pad,value);FlushKeyInput();}}}
 void RefreshInputOptions(){if(keyDraft==null||keyContent==null)return;var c=player?.InputCharacter;characterTab.GetComponentInChildren<Text>().text=c==null?"キャラ未選択":c.characterName;keyNote.text=characterMode?"キャラ操作のslotだけを入れ替えます。物理bindingは参照のみです。":"基本bindingは全キャラ共通です。行を選択しKeyboard / Padを入力。";foreach(var pair in keyRows){var row=keyDraft.Row(pair.Key);pair.Value.gameObject.SetActive(row.context!="Battle"||!characterMode);pair.Value.GetComponentInChildren<Text>().text=RowName(row.id);keyKeyboard[row.id].text=BindingText(row.keyboard);keyPad[row.id].text=BindingText(row.pad);}for(int i=0;i<9;i++){var button=operationRows[i];button.gameObject.SetActive(characterMode&&c!=null);if(c!=null){var op=c.attackSlots[i];var slot=(BattleAttackSlot)keyDraft.Slot(c,op);var binding=keyDraft.Row(KeyConfigProfile.SlotId(slot));button.GetComponentInChildren<Text>().text=OpName(op.displayName)+" → "+slot+"    ["+BindingText(binding.keyboard)+" / "+BindingText(binding.pad)+"]";}slotChoices[i].gameObject.SetActive(characterMode&&pendingOperation!=null);}}
